---
/**
 * @title Pagination
 * @level liftoff
 * @description Themed previous/next navigation with real links.
 * @category Content
 * @hydration none
 * @accessibility
 * - Renders a labelled `<nav>` with native anchors and no disabled tab stops.
 * @keyboard
 * - Native link keyboard behavior.
 */

import "./content.css";

type Props = {
  previousHref?: string;
  previousLabel?: string;
  nextHref?: string;
  nextLabel?: string;
};
const { previousHref, previousLabel = "Previous", nextHref, nextLabel = "Next" } = Astro.props as Props;

---

<nav data-lsui-pagination aria-label="Pagination">
  {previousHref && <a href={previousHref} rel="prev">{previousLabel}</a>}
  {nextHref && <a href={nextHref} rel="next">{nextLabel}</a>}
</nav>

/* LightSpeedUI Level 2 — content and publishing styles; semantic tokens only. */
@layer lsui {
  @layer components {
    [data-lsui-prose],
    [data-lsui-portable-text],
    [data-lsui-blocks] {
      color: var(--color-text);
      font-family: var(--font-body);
      line-height: var(--leading-relaxed);
    }

    [data-lsui-prose] :is(h1, h2, h3, h4) {
      line-height: var(--leading-tight);
      margin-block-start: var(--space-lg);
    }

    [data-lsui-byline],
    [data-lsui-post-meta] {
      display: flex;
      flex-wrap: wrap;
      gap: var(--space-2);
      color: var(--color-text-muted);
      font-size: var(--text-sm);
    }

    [data-lsui-post-card] {
      display: grid;
      gap: var(--space-2);
      padding: var(--space-md);
      border: var(--border-width) solid var(--color-border);
      border-radius: var(--radius-md);
      background: var(--color-surface);
      color: var(--color-text);
    }

    [data-lsui-post-card] a {
      color: var(--color-text);
      text-decoration-thickness: var(--border-width);
      text-underline-offset: var(--space-1);
    }

    [data-lsui-toc] nav ul {
      list-style: none;
      padding-inline-start: 0;
    }

    [data-lsui-pagination] {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: var(--space-md);
      padding-block: var(--space-lg);
    }

    [data-lsui-pagination] a {
      min-block-size: var(--target-min-size, 1.5rem);
      color: var(--color-text);
    }
  }
}
